        <input id="${id}" type="radio" name="notificationPreference" value="${value}" required>
        <span class="radio-copy">${label}</span>
      </label>
    `;

    const NotificationPreferenceField = () => `
      <div class="form-field">
        <fieldset id="notification-fieldset" aria-describedby="notification-help">
          <legend>
