            ${RadioOption({ id: "notify-push", value: "Push Notifications", label: "Push Notifications" })}
          </div>
          <p class="field-error" id="notification-error" hidden>Error: Select how you prefer to receive notifications.</p>
        </fieldset>
      </div>
    `;

    const SubmitButton = () => `
      <div class="actions">
        <button type="submit">Save preference</button>
      </div>
    `;

    const App = () => `
      <div class="page-shell">
        <p class="eyebrow">Preferences</p>
        <h1>Notification settings</h1>
        <p class="intro">Tell us the best way to keep you informed. This quick form lets you choose one notification channel.</p>
        <form id="notification-form" novalidate>
          ${NotificationPreferenceField()}
          ${SubmitButton()}
          <p class="form-status" id="form-status" aria-live="polite"></p>
        </form>
      </div>
    `;

    document.getElementById("app").innerHTML = App();

    const form = document.getElementById("notification-form");
    const radios = Array.from(form.elements.notificationPreference);
    const fieldset = document.getElementById("notification-fieldset");
    const error = document.getElementById("notification-error");
    const status = document.getElementById("form-status");

    function clearError() {
      error.hidden = true;
      fieldset.setAttribute("aria-describedby", "notification-help");
      radios.forEach((radio) => radio.removeAttribute("aria-invalid"));
