      radio.addEventListener("change", () => {
        clearError();
        status.textContent = "";
      });
    });

    form.addEventListener("submit", (event) => {
      event.preventDefault();

      const selectedRadio = radios.find((radio) => radio.checked);

      if (!selectedRadio) {
        status.textContent = "";
        showError();
        return;
