 <body>
   <a class="skip-link" href="#main-content">Skip to main content</a>
   <main id="main-content" tabindex="-1">
     <div id="app"></div>
   </main>

   <script>
     const RadioOption = ({ id, value, label }) => `
       <label class="radio-card" for="${id}">
         <input id="${id}" type="radio" name="notificationPreference" value="${value}" required>
         <span class="radio-copy">${label}</span>
       </label>
     `;

     const NotificationPreferenceField = () => `
       <div class="form-field">
         <fieldset id="notification-fieldset" aria-describedby="notification-help">
           <legend>
             How do you prefer to receive notifications?
             <span class="required-marker" aria-hidden="true">*</span>
           </legend>
           <p class="field-hint" id="notification-help">Choose one option before saving your preference.</p>
           <div class="radio-group">
             ${RadioOption({ id: "notify-email", value: "Email", label: "Email" })}
             ${RadioOption({ id: "notify-sms", value: "SMS", label: "SMS" })}
             ${RadioOption({ id: "notify-push", value: "Push Notifications", label: "Push Notifications" })}
           </div>
           <p class="field-error" id="notification-error" hidden>Error: Select how you prefer to receive notifications.</p>
         </fieldset>
       </div>
     `;

     const SubmitButton = () => `
       <div class="actions">
         <button type="submit">Save preference</button>
       </div>
     `;

     const App = () => `
       <div class="page-shell">
         <p class="eyebrow">Preferences</p>
         <h1>Notification settings</h1>
         <p class="intro">Tell us the best way to keep you informed. This quick form lets you choose one notification channel.</p>
         <form id="notification-form" novalidate>
           ${NotificationPreferenceField()}
           ${SubmitButton()}
           <p class="form-status" id="form-status" aria-live="polite"></p>
         </form>
       </div>
     `;

     document.getElementById("app").innerHTML = App();

     const form = document.getElementById("notification-form");
     const radios = Array.from(form.elements.notificationPreference);
     const fieldset = document.getElementById("notification-fieldset");
     const error = document.getElementById("notification-error");
     const status = document.getElementById("form-status");

     function clearError() {
       error.hidden = true;
       fieldset.setAttribute("aria-describedby", "notification-help");
       radios.forEach((radio) => radio.removeAttribute("aria-invalid"));
     }

     function showError() {
       error.hidden = false;
       fieldset.setAttribute("aria-describedby", "notification-help notification-error");
       radios.forEach((radio) => radio.setAttribute("aria-invalid", "true"));
       radios[0].focus();
     }

     radios.forEach((radio) => {
       radio.addEventListener("change", () => {
         clearError();
         status.textContent = "";
       });
     });

     form.addEventListener("submit", (event) => {
       event.preventDefault();

       const selectedRadio = radios.find((radio) => radio.checked);

       if (!selectedRadio) {
         status.textContent = "";
         showError();
         return;
       }

       clearError();
       status.textContent = `Preference saved: ${selectedRadio.value}.`;
     });
   </script>
 </body>
 </html>

